    "ieltsSpeaking.p.sha.how": "Алдымен тыңдаңыз, содан кейін дауыстап қайталаңыз — диктордан кейін немесе онымен бірге. «|» — мағыналық топтың шекарасы, қысқа үзіліс орны. Сөйлемді соңына дейін тыңдасаңыз немесе өзіңізді жазып алсаңыз, ол өтілді деп саналады.",
