    "ieltsSpeaking.p.skipRecordedTitle": "Сұрақты өткізіп жібересіз бе?",
    "ieltsSpeaking.p.skipRecordedText": "Жауап жазылып қойған. Сұрақты өткізіп жіберсеңіз, жазба өшіріледі және ол жұмысқа кірмейді.",
    "ieltsSpeaking.p.skip": "Өткізіп жіберу",
    "ieltsSpeaking.p.skipped": "Өткізілді",
    "ieltsSpeaking.p.skippedText": "Бұл сұраққа жауап жазылмаған және жұмысқа кірмейді. Оны қазір де жазуға болады — жоғарыдағы микрофон батырмасы.",
    "ieltsSpeaking.p.gate.record": "Әрі қарай — жауапты жазғаннан кейін. Жауап бергіңіз келмесе, «Өткізіп жіберу» батырмасын басыңыз.",
    "ieltsSpeaking.p.gate.none": "Сессияны сақтау үшін кемінде бір жауапты жазыңыз.",
    "ieltsSpeaking.p.gate.skipped": "Сұрақ өткізілді — оны қазір жазуға немесе кейін оған қайтуға болады.",
    "ieltsSpeaking.p.title": "Speaking",
    "ieltsSpeaking.p.sub": "Емтиханның үш бөлігі: жауапты жазып алу, сөйлеу көрсеткіштері және band 8 үлгі жауаптары",
    "ieltsSpeaking.p.hero.title": "ЖИ бағалауы қосылуда",
    "ieltsSpeaking.p.hero.text": "Жазбалар сақталып, төрт критерий бойынша бағалауды күтеді. Әр жауаптан кейін бірден — ұзақтығы, сөйлеу үлесі, үзілістер және дауыс қаттылығы, сондай-ақ талдауы бар үлгі жауап. Band ЖИ-мен бірге шығады.",
    "ieltsSpeaking.p.hero.teacher": "Сіздің оқу маршрутыңыз — оқытушымен: сессиядан кейін жазбаларды WhatsApp арқылы жіберіңіз, оқытушы тыңдайды.",
