    "ieltsWriting.p.sc.noBand": "Мұнда балл қойылмайды — оны ЖИ тексерісі береді.",
    "ieltsWriting.p.sc.sumEmpty": "Жоғарыдағы сұрақтарға жауап беріңіз — мұнда не шыққаны және неге көңіл бөлу керегі көрсетіледі.",
